from pathlib import Path
import json,shutil
from numbered import symbol,group_onsets
out=Path('outputs/查看识谱结果/20-直接数字音符预览');out.mkdir(parents=True,exist_ok=True)
src=Path('outputs/查看识谱结果/19-全段多模型交叉对照')
data=json.loads((src/'完整对照数据.json').read_text());models={m:[] for m in data['summary']['events']}
for row in data['rows']:
 for m,n in row['models'].items():
  digit,octave=symbol(n['pitch']);models[m].append({**n,'digit':digit,'octave':octave,'disputed':bool(row['flags']),'comparison_row':row['id']})
for m,ns in models.items():
 assert len(ns)==data['summary']['events'][m]
 assert len({n['id'] for n in ns})==len(ns)
original=json.loads((src/'原始输出/AnthemScore-默认编排结果.json').read_text())['notes']
models['AnthemScore']=[{**n,'id':f'anthem-{i}','digit':symbol(n['pitch'])[0],'octave':symbol(n['pitch'])[1],'disputed':False} for i,n in enumerate(original)]
grouped={m:group_onsets(ns) for m,ns in models.items()}
shutil.copyfile(src/'原始录音.mp3',out/'原始录音.mp3')
(out/'数字音符数据.json').write_text(json.dumps(grouped,ensure_ascii=False,indent=2))
page='''<!doctype html><html lang="zh"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>直接数字音符预览</title>
<style>*{box-sizing:border-box}body{margin:0;background:#f6f5f0;color:#20382f;font:16px/1.6 system-ui}main{max-width:1200px;margin:auto;padding:32px 24px}h1{font-size:32px;margin:0}p{margin:8px 0}.intro{max-width:850px;color:#52665d}.controls{position:sticky;top:0;z-index:2;background:#f6f5f0f5;padding:16px 0;border-bottom:1px solid #cfd8cf}select,button{font:inherit;padding:8px 12px;border:1px solid #bdcfc2;background:white;border-radius:8px}audio{width:100%;height:40px;margin-top:10px}.legend{background:#e7efe8;border-radius:12px;padding:14px;margin:20px 0}.cards{display:grid;grid-template-columns:repeat(auto-fill,minmax(170px,1fr));gap:14px}.card{background:white;border:1px solid #d8e0d8;border-radius:12px;padding:12px;align-self:start}.card.active{outline:3px solid #36835d}.time{font-size:13px;color:#53685b;margin-bottom:12px}.event{display:flex;align-items:center;gap:10px;border-top:1px solid #edf0eb;padding:5px 0;min-height:86px}.symbol{display:flex;flex-direction:column;align-items:center;width:45px;flex-shrink:0;line-height:16px}.digit{font-size:34px;line-height:38px;font-weight:650}.dots{font-size:15px;min-height:16px;letter-spacing:1px}.meta{font-size:12px;color:#5b6c62}.warn{color:#986200}.bar{height:4px;background:#6d9c7e;margin-top:6px;border-radius:3px}.empty{padding:40px;color:#65746a}footer{margin-top:24px;font-size:13px;color:#637669}</style>
<main><h1>把模型听到的音，直接写成数字</h1><p class="intro">固定 1=C，中央 C（C4）为不加点的 1。上点表示高八度，下点表示低八度。没有经过五线谱或 MusicXML。</p>
<div class="legend"><strong>这是一份音符预览，还不是规范简谱。</strong>数字旁的秒数是模型输出的原始时间；下方绿色条只表示持续长短，不是减时线。分组内各音起音相差不超过60毫秒，仅方便查看，不代表确认了和弦或左右手。</div>
<div class="controls"><label>模型 <select id="model"><option value="BP">Basic Pitch</option><option value="Piano">钢琴专用模型</option><option value="Omni">Omnizart Piano</option><option value="OmniV2">Omnizart PianoV2</option><option value="AnthemScore">AnthemScore（编排结果，前30秒）</option></select></label> <label>片段 <select id="segment"></select></label> <button id="focus">看 27.6 秒 E3/E4</button><p id="status"></p><audio id="audio" controls src="原始录音.mp3"></audio><p class="meta">播放的是原始录音，不是模型生成的声音。橙色“有分歧”包含音高对应、起音或时值差异，不代表已确认错音。</p></div>
<div id="cards" class="cards"></div><footer>四个模型的832个事件全部保留；切换模型只改变显示。没有自动删音、补音、改变时值或推断调性。AnthemScore的91个事件来自它已有的编排输出，与另外四个原始模型输出性质不同。</footer></main>
<script>const DATA=__DATA__;const names={BP:'Basic Pitch',Piano:'钢琴模型',Omni:'Omni Piano',OmniV2:'Omni PianoV2',AnthemScore:'AnthemScore'};const model=document.getElementById('model'),segment=document.getElementById('segment'),audio=document.getElementById('audio');for(let t=0;t<60;t+=10){const o=document.createElement('option');o.value=t;o.textContent=t+'–'+Math.min(t+10,52.06)+' 秒';segment.append(o);}function pitch(p){return ['C','C♯','D','D♯','E','F','F♯','G','G♯','A','A♯','B'][p%12]+(Math.floor(p/12)-1);}function render(){const t=+segment.value,m=model.value;const groups=DATA[m].map(g=>g.filter(n=>n.start>=t&&n.start<Math.min(t+10,52.07))).filter(g=>g.length);let total=0;document.getElementById('cards').innerHTML=groups.map(g=>{total+=g.length;return '<article class="card" data-start="'+g[0].start+'" data-end="'+Math.max(...g.map(n=>n.start+n.duration))+'"><div class="time"><button onclick="listen('+Math.max(0,g[0].start-.15)+')">▶ '+g[0].start.toFixed(2)+' 秒</button><br>'+ (g.length>1?'近同时起音 · '+g.length+' 个音':'单个起音')+'</div>'+g.sort((a,b)=>b.pitch-a.pitch).map(n=>'<div class="event" title="'+pitch(n.pitch)+'"><div class="symbol"><span class="dots">'+(n.octave>0?'•'.repeat(n.octave):'&nbsp;')+'</span><span class="digit">'+n.digit+'</span><span class="dots">'+(n.octave<0?'•'.repeat(-n.octave):'&nbsp;')+'</span></div><div class="meta">'+pitch(n.pitch)+'<br>'+n.start.toFixed(3)+'s 开始<br>持续 '+n.duration.toFixed(3)+'s'+(n.disputed?'<br><span class="warn">有分歧，待核查</span>':'')+'<div class="bar" style="width:'+Math.min(90,n.duration*65)+'px"></div></div></div>').join('')+'</article>';}).join('')||'<p class="empty">'+(m==='AnthemScore'&&t>=30?'AnthemScore 现有结果未覆盖这一段。':'这段没有模型起音事件。')+'</p>';document.getElementById('status').textContent=names[m]+' · 本段 '+total+' 个音符（保留原始事件）';}function listen(t){audio.currentTime=t;audio.play().catch(()=>{});}model.onchange=render;segment.onchange=render;document.getElementById('focus').onclick=()=>{segment.value=20;render();listen(26.8);const card=[...document.querySelectorAll('.card')].find(c=>+c.dataset.start>=27.5);card?.scrollIntoView({block:'center',behavior:'smooth'});};audio.ontimeupdate=()=>document.querySelectorAll('.card').forEach(c=>c.classList.toggle('active',audio.currentTime>=+c.dataset.start&&audio.currentTime<+c.dataset.end));render();</script></html>'''
page=page.replace('__DATA__',json.dumps(grouped,ensure_ascii=False).replace('</','<\\/'))
(out/'先看这里.html').write_text(page)
print({m:sum(map(len,gs)) for m,gs in grouped.items()})
